import { useQuery } from "@tanstack/react-query";
import { api } from "../services/api";

export function useEdaReport() {
  return useQuery({
    queryKey: ["eda"],
    queryFn: api.getEdaReport,
    // The report is regenerated by a batch job, not by user actions.
    staleTime: 30 * 60 * 1000,
  });
}
